CREATE DATABASE IF NOT EXISTS smartstudent;USE smartstudent;CREATE TABLE IF NOT EXISTS students(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,roll_no VARCHAR(30) UNIQUE NOT NULL,department VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,phone VARCHAR(20) NOT NULL,marks DECIMAL(5,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);CREATE INDEX idx_department ON students(department);CREATE INDEX idx_marks ON students(marks);
